inline const Postproc *find_postproc(const PostprocRow *rows, int n, const char *name) {
	for (int i = 0; i < n; ++i)
		if (!std::strcmp(rows[i].name, name)) return &rows[i].pp;
	return nullptr;
}
inline const Postproc *biome_postproc(const char *biome) {
	return find_postproc(kBiomePostproc, (int)(sizeof(kBiomePostproc) / sizeof(kBiomePostproc[0])), biome);
}
inline const Postproc *map_postproc(const char *map_id) {
	return find_postproc(kMapPostproc, (int)(sizeof(kMapPostproc) / sizeof(kMapPostproc[0])), map_id);
}

